-- 2026-10-19. Descriptions and logos for the 31 breeders migration 0023 added, approved by Alex on 2026-10-19
-- ("Approved, apply the descriptions and logos to staging"). Each description is drawn only from the kennel's own
-- website or its Responsible Dog Breeder Network member page, and County Line Kennel's from Amber's Wix breeder page.
-- The source page for every fact is in hs-seo-data/puppyconnection/2026-10-18-descriptions (drafts.json, review.html).
-- The 20 kennels with a website of their own get the logo from it, already uploaded to R2 puppyconnection-files at
-- brand/<breeder id>/logo-2026101926.webp with a .card copy (Ibar's full file is smaller than a card, so it has none).
-- Each UPDATE only fills an empty description or logo, so a breeder's own later edit is left alone and a second run
-- changes nothing. Run once on staging after a backup, with ops/d1-apply.mjs.

-- Pleasant View Puppies
UPDATE breeder_profiles SET description = 'Pleasant View Puppies is Nathan Steury''s family-run program in Osseo, Michigan, raising Cavapoo and Mini Bernedoodle puppies. Nathan credits his grandfather with teaching him that caring for animals is a calling and a responsibility to look after well. The dogs live in a facility with heated floors, hydronic-heated kennel decks, shaded outdoor areas and a fenced play space. Parent dogs come from champion stock and are OFA tested and cleared, and the program keeps one or two litters at a time, so visits and placements are scheduled ahead through a waitlist.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-pleasantviewpuppies' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-pleasantviewpuppies/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-pleasantviewpuppies' AND logo_key IS NULL;
-- Rolling Acres Farm Puppies
UPDATE breeder_profiles SET description = 'Rolling Acres Farm Puppies is Leon Schrock''s family program on a 12-acre place among the cornfields of Humboldt, in central Illinois, raising Poodles and Boston Terriers. The family works closely with their veterinarian and researches the bloodlines and genetics behind each pairing. Puppies are handled and socialized from their first day by every member of the family. Each one goes home up to date on vaccinations and deworming, with a health certificate, a microchip, a two-year guarantee against genetic defects and a puppy pack that includes a homemade blanket.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-rollingacresfarmpuppies' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-rollingacresfarmpuppies/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-rollingacresfarmpuppies' AND logo_key IS NULL;
-- Cuddly Family Companions
UPDATE breeder_profiles SET description = 'Cuddly Family Companions is Leroy and Becky Ann Esh''s family program in Greens Fork, Indiana. They began raising Yorkies in 2021 and have since added Shih Tzus, Mini Schnauzers, Cavaliers and Great Danes. Leroy grew up on a dairy farm and still raises horses and works as a farrier, and the couple''s six children at home help care for the dogs. Puppies get early neurological stimulation in their first days and outdoor play when the weather allows, while the adult dogs are exercised every day.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-cuddlyfamilycompanions' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-cuddlyfamilycompanions/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-cuddlyfamilycompanions' AND logo_key IS NULL;
-- Teapup
UPDATE breeder_profiles SET description = 'Teapup is a family business in Syracuse, Indiana. Dan and Deb Beer began raising dogs in 1989, and when they retired in 2023 they handed the business to their granddaughter and her husband, Justin and Deborah Zimmerman. Teapup is open Monday to Friday from 9am to 5pm and Saturday from 9am to 3pm, and other times are available on request.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-teapup' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-teapup/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-teapup' AND logo_key IS NULL;
-- Marlor Homestead Companions
UPDATE breeder_profiles SET description = 'Marlor Homestead Companions is Lorene Martin''s family program in Carson City, Michigan, raising Cavalier King Charles Spaniels, Cavapoos, Shih Tzus and Shorkies. Gentle socialization starts when the puppies are two weeks old, so they meet new sights, sounds and touches early. Lorene''s household is a family of nine, and every puppy gets daily attention, snuggles and playtime with the children.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-marlorhomesteadcompanions' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-marlorhomesteadcompanions/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-marlorhomesteadcompanions' AND logo_key IS NULL;
-- TM Countryside K9
UPDATE breeder_profiles SET description = 'TM Countryside K9 is Titus and Melva Burkholder''s family program in Goshen, Indiana. Their site says their love of dogs started 17 years ago with Great Danes, and they have since added Mini Dachshunds and Corgis for families who want a smaller companion. The adult dogs are checked regularly by a veterinarian and have both indoor and outdoor space, with extra care given to nursing mothers. Each puppy leaves vet checked, microchipped and current on vaccinations and dewormings, with registration papers, a health guarantee, a puppy care package and lifetime support from the family.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-tmcountrysidek9' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-tmcountrysidek9/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-tmcountrysidek9' AND logo_key IS NULL;
-- Precious Paws Companions
UPDATE breeder_profiles SET description = 'Precious Paws Companions is Eli and Lori Yoder''s family of five, living on a 70-acre beef farm in the rolling hills of Holmes County, Ohio, near Millersburg. They began with Labradoodles in 2019 and added French Bulldogs in 2023, and today they raise Miniature Aussiedoodles, Miniature Goldendoodles and French Bulldogs. Farm life gives the puppies room to play and grow around the family. Every litter is socialized early and starts crate, potty and leash training before the puppies go home.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-preciouspawscompanions' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-preciouspawscompanions/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-preciouspawscompanions' AND logo_key IS NULL;
-- Double YY Puppies
UPDATE breeder_profiles SET description = 'Double YY Puppies is the Yoder family''s program in Arthur, Illinois, run by Merlin Yoder with his wife, Ruth, and their two children, and raising Shih Tzu and Teddy Bear puppies. Merlin bought his first dog at 15, and the family began breeding in October 2021. Families are welcome to visit, meet the family and see where their puppy was raised. Each puppy goes home with its paperwork, a small bag of food, a toy, a leash and collar, and a blanket.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-doubleyypuppies' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-doubleyypuppies/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-doubleyypuppies' AND logo_key IS NULL;
-- King's Family Companions
UPDATE breeder_profiles SET description = 'King''s Family Companions is Abner King''s family program in the countryside of Ronks, Pennsylvania, raising English Bulldogs and Boston Terriers since 2010. It began when Abner''s father-in-law gave him an English Bulldog of his own, and the Boston Terriers came later. With seven children in the house, the puppies grow up around the everyday sights, sounds and handling of a busy family. The Kings also run an organic produce farm in Lancaster County, growing onions, strawberries, potatoes and other crops through the year.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-kingsfamilycompanions' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-kingsfamilycompanions/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-kingsfamilycompanions' AND logo_key IS NULL;
-- Gold Paw Canine
UPDATE breeder_profiles SET description = 'Gold Paw Canine is Jonas and Barbie''s English Bulldog program on their dairy farm in Kinzers, Pennsylvania. The puppies grow up with regular human contact, age-appropriate socialization and a steady daily routine, around the normal sounds of the house and the farm. Each one has vet checks, deworming, vaccinations and a microchip before going home. The family takes time to talk with each family about temperament, care and what owning a Bulldog involves, and visits are by appointment.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-goldpawcanine' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-goldpawcanine/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-goldpawcanine' AND logo_key IS NULL;
-- Pine Acres Puppies
UPDATE breeder_profiles SET description = 'Pine Acres Puppies is Sam and Rachel Smucker''s family program in Kinzers, Pennsylvania, in Lancaster County. The family started raising Cavalier King Charles Spaniels and Maltese in 2005, and their five children help socialize and care for every puppy. They value both breeds for their gentle nature and trainability, and they help families looking for a therapy dog, a companion for a child with special needs or simply a new best friend.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-pineacrespuppies' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-pineacrespuppies/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-pineacrespuppies' AND logo_key IS NULL;
-- Sweet Puppy Paws
UPDATE breeder_profiles SET description = 'Sweet Puppy Paws is Justin and Deborah''s family program in Syracuse, Indiana, raising Labradors in all three American Kennel Club colors, black, yellow and chocolate. Their yellows range from a light white to a fox red, and they aim for the English style of Labrador, with a blocky head, a stocky body, big paws and a kind expression. Now and then they also have a litter of Bernese Mountain Dog or Golden Retriever puppies.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-sweetpuppypaws' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-sweetpuppypaws/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-sweetpuppypaws' AND logo_key IS NULL;
-- Family Affair Puppies
UPDATE breeder_profiles SET description = 'Family Affair Puppies is Leona Troyer''s family-owned program in Topeka, Indiana, raising companion breeds that include Cavapoos, Golden Retrievers, Maltipoos and Shih Tzus. It started as a small family hobby, and every litter is born and raised in the daily rhythm of family life, with handling from children and adults and supervised play indoors and out. Every parent dog is health tested for hips, elbows, eyes and relevant genetic conditions before it joins the program. Visits are by appointment after first contact.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-familyaffairpuppies' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-familyaffairpuppies/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-familyaffairpuppies' AND logo_key IS NULL;
-- Sunset Paw Babies
UPDATE breeder_profiles SET description = 'Sunset Paw Babies is Anthony and Sarah Yoder''s family program in Sullivan, Illinois, raising Golden Retrievers, Cavalier King Charles Spaniels and Miniature Goldendoodles since 2019. The family holds a USDA Class A breeder license, certificate 33-A-0628. Their children help with age-appropriate time with the puppies, which also get early neurological stimulation, a start on potty training and an introduction to the leash. When they are not with the dogs, the family enjoys camping, golfing and hunting together.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-sunsetpawbabies' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-sunsetpawbabies/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-sunsetpawbabies' AND logo_key IS NULL;
-- Ibar Canine Companions
UPDATE breeder_profiles SET description = 'Ibar Canine Companions is Ivan and Barbie''s family program in Honey Brook, Pennsylvania, raising Boxers and Miniature Dachshunds with the help of their six children. The name comes from Ivan''s first initial and the first three letters of Barbie''s name. The family uses and recommends NuVet supplements and the Good Dog One-der training approach, and they are glad to answer questions by text, email or phone or to introduce a puppy over FaceTime.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-ibarcaninecompanions' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-ibarcaninecompanions/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-ibarcaninecompanions' AND logo_key IS NULL;
-- Rocky Top Bulldogs
UPDATE breeder_profiles SET description = 'Rocky Top Bulldogs is Ben and Grace Mullet''s family program on their homestead near Shipshewana, Indiana, where they live with their three daughters, a pony and plenty of chickens. They started with Cavapoos six years ago and switched to English Bulldogs about three years ago, drawn by the breed''s personality and temperament. The adult dogs are OFA evaluated and get daily play in a yard with tunnels, ramps and toys, and the puppies are introduced to a leash before they go home.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-rockytopbulldogs' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-rockytopbulldogs/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-rockytopbulldogs' AND logo_key IS NULL;
-- Perfect Match Poodles
UPDATE breeder_profiles SET description = 'Perfect Match Poodles is Gabriel and Joyce''s family program in Nappanee, Indiana, raising Miniature Poodles since 2018 under the saying "Prepare To Be Loved." They focus on matching each puppy''s temperament and energy to the right family. The program is USDA and BOAH licensed and Canine Care Certified, and the dogs have the run of a yard with playsets the family built for them. Puppies are handled and played with every day from birth and have a full veterinary exam at six to seven weeks.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-perfectmatchpoodles' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-perfectmatchpoodles/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-perfectmatchpoodles' AND logo_key IS NULL;
-- Paw Print Acres
UPDATE breeder_profiles SET description = 'Paw Print Acres is Joni and Norma Jean''s family of nine on a third-generation family farm in Wakarusa, Indiana. They have raised dogs for more than 11 years, starting with Boston Terriers and Cocker Spaniels and later adding Saint Bernards as a larger dog that fits farm life. The puppies grow up around the children and the farm''s horses, cows, sheep, chickens and cats. Every parent dog has DNA and OFA health testing, and leash training begins before the puppies go home.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-pawprintacres' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-pawprintacres/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-pawprintacres' AND logo_key IS NULL;
-- Maple Lane Pets
UPDATE breeder_profiles SET description = 'Maple Lane Pets is Lonnie Miller''s small home-based program in Topeka, Indiana, raising Cavapoos, Shih-Poos, Papillons and Shih Tzus. Lonnie began raising puppies at 21, and the program stays small on purpose, with seven breeding females and about twenty puppies a year. Puppies are born and raised at home, played with in different rooms of the house and around children, and started on crate training before they leave. The adult dogs are DNA and OFA tested, and each puppy goes home with Royal Canin starter food and a familiar blanket.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-maplelanepets' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-maplelanepets/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-maplelanepets' AND logo_key IS NULL;
-- Willow Lane Bulldogs
UPDATE breeder_profiles SET description = 'Willow Lane Bulldogs is Eric Yoder''s family program in Millersburg, Indiana, raising English Bulldogs and Bulldog crosses since 2024. The family''s two daughters play with the puppies every day, and Eric gives each one individual time as well, so the family can describe each puppy''s personality to the families who ask. Eric also runs a woodworking business. Each puppy goes home with about a week of food, care literature, its vet exam receipt and its vaccination and deworming records.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-willowlanebulldogs' AND (description IS NULL OR trim(description) = '');
UPDATE breeder_profiles SET logo_key = 'brand/seed-willowlanebulldogs/logo-2026101926.webp', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-willowlanebulldogs' AND logo_key IS NULL;
-- Johnny Miller
UPDATE breeder_profiles SET description = 'Johnny Miller runs a small French Bulldog program in Goshen, Indiana, raising the breed because he enjoys it and wants to place healthy, well-started puppies in good homes. Puppies are handled every day from birth and socialized with children, so they are used to people and everyday sounds before they go home. Each one sees a veterinarian before leaving and goes home with a small bag of the food it is used to.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-johnny-miller' AND (description IS NULL OR trim(description) = '');
-- Duane Borkholder
UPDATE breeder_profiles SET description = 'Duane Borkholder runs a small professional kennel in Milford, Indiana, raising Miniature Dachshunds and Miniature Poodles, and he has been breeding since 2009. Puppies get daily handling and time with children, and crate training starts early. Each litter goes through genetic testing, every puppy has a veterinary check before going home, and each one leaves with a small bag of its food and a blanket for the move.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-duane-borkholder' AND (description IS NULL OR trim(description) = '');
-- Countryview Pets
UPDATE breeder_profiles SET description = 'Countryview Pets is Daniel Miller''s small Yorkshire Terrier program in Ligonier, Indiana. Puppies are raised in a warm, climate-controlled setting, handled regularly and socialized with children from an early age. Each puppy is seen by a veterinarian and microchipped before it leaves, and goes home with a blanket that smells familiar, toys and a small bag of its food. Daniel is working toward genetic health testing and OFA certification for his dogs.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-countryview-pets' AND (description IS NULL OR trim(description) = '');
-- Riverdale Paw Pals
UPDATE breeder_profiles SET description = 'Riverdale Paw Pals is Philip Imhoff''s program in Rochester, Indiana, raising Cavalier King Charles Spaniels, Corgis, Miniature Dachshunds and Basset Hounds. Philip has been breeding for 20 years, the kennel is USDA licensed (32-A-0765), and the breeding dogs are health tested through OFA and genetic testing. Children are part of the puppies'' day in the kennel, and leash training starts before they go home with their vaccinations, food and toys.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-riverdale-paw-pals' AND (description IS NULL OR trim(description) = '');
-- Little Paws Canine
UPDATE breeder_profiles SET description = 'Little Paws Canine is Wayne Miller''s small program in Topeka, Indiana, raising Papillons and Cavapoos in a home setting where each litter gets proper attention. Puppies are around everyday sights, sounds and handling from an early age. Each one has a veterinary health check and its age-appropriate vaccinations before going home, along with a small supply of its food and health records to share with the new family''s own veterinarian.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-little-paws-canine' AND (description IS NULL OR trim(description) = '');
-- Wagging Tail Puppies
UPDATE breeder_profiles SET description = 'Wagging Tail Puppies is a new Cavalier King Charles Spaniel program in Goshen, Indiana. Puppies are born and raised in a heated kennel kept comfortable and homey, with children around them every day so they grow used to the sounds and activity of a real household. The dogs have genetic health testing now, with OFA testing planned as the program grows. Each puppy has a veterinary exam and goes home with its vaccinations, a registered microchip and a small bag of its food.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-wagging-tail-puppies' AND (description IS NULL OR trim(description) = '');
-- Signature Puppies
UPDATE breeder_profiles SET description = 'Signature Puppies is DeWayne Yoder''s small program in LaGrange, Indiana, raising Pomeranians and Yorkshire Terriers. The program stays small so every puppy gets real attention, and the puppies are raised in a home setting where they are handled daily. Each one has a veterinary check and its vaccinations before going home, is dewormed on schedule, and leaves with its health records and enough food to ease the move.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-signature-puppies' AND (description IS NULL OR trim(description) = '');
-- Cozy Pine Canine
UPDATE breeder_profiles SET description = 'Cozy Pine Canine is Gerald and Kayla Bontrager''s program on a six-acre farmette in Topeka, Indiana, raising Biewer Terriers, Cavapoos and Shih Tzus. They have raised puppies for nine years alongside their two children, ducks, horses and a garden. The puppies'' space is washed daily and disinfected weekly, the dogs have a full DNA panel and eyes certified by an OFA-affiliated ophthalmologist, and puppies are vaccinated at six, eight and ten weeks and microchipped. Most go home at about ten weeks, and the family keeps Sundays for church and family, with no calls or visits that day.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-cozy-pine-canine' AND (description IS NULL OR trim(description) = '');
-- Tyler & Eileen Martin
UPDATE breeder_profiles SET description = 'Tyler and Eileen Martin raise Corgis in Goshen, Indiana, and have kept their program small and straightforward since they began breeding in 2021. They run genetic and DNA testing on their dogs before breeding. The puppies are raised in a climate-controlled space as part of daily life, so they are used to everyday sounds and handling, and each goes home with its vaccinations and a small bag of the food it already eats.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-tyler-eileen-martin' AND (description IS NULL OR trim(description) = '');
-- Pine Creek Bulldogs
UPDATE breeder_profiles SET description = 'Pine Creek Bulldogs is Marcus Lehman''s small English Bulldog program in Milford, Indiana, raising the breed because he loves it and wants each puppy to go to a home that will love it just as much. Puppies are handled daily and introduced to everyday sights and sounds from the start. Each one has a veterinary check before going home, along with its vaccinations, a small supply of its food, a record of its care and the family''s contact details for questions later.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-pine-creek-bulldogs' AND (description IS NULL OR trim(description) = '');
-- County Line Kennel
UPDATE breeder_profiles SET description = 'County Line Kennel is run by Gerald and his son John, an easygoing father and son team with a quiet passion for dogs. John grooms the dogs and has a stress-free approach to baths and haircuts, while Gerald gets to know the families who call or visit. Every dog is AKC registered, has regular veterinary exams and gets daily exercise outside. The kennel is USDA licensed and inspected every year, they work with Furry Freight when a family needs transportation, and they keep Sundays for church and family.', updated_at = '2026-10-19T12:00:00Z', version = version + 1 WHERE breeder_id = 'seed-county-line-kennel' AND (description IS NULL OR trim(description) = '');

-- Mark the site for the next publish.
UPDATE site_state SET dirty = 1, dirty_since = COALESCE(dirty_since, strftime('%Y-%m-%dT%H:%M:%fZ','now')), generation = generation + 1 WHERE id = 1;
